<script lang="ts">
  import Icon from './Icon.svelte';
  import { localDateTime, occurrenceTime, parseNonNegativeAmount, type Investment, type InvestmentEvent, type InvestmentEventKind, type Ledger } from './finance';
  import { eventLabels, investmentStats, recordInvestmentEvent, removeInvestment, removeInvestmentEvent } from './investments';
  let { ledger, busy, disabled, commit, getError }: { ledger: Ledger; busy: boolean; disabled: boolean; commit: (transform: (current: Ledger) => Ledger) => Promise<boolean>; getError: () => string } = $props();
  const money = (minor: number) => new Intl.NumberFormat('en-EG', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(minor / 100);
  const roi = (value: number | null) => value === null ? 'Not available' : `${value > 0 ? '+' : ''}${value.toFixed(2)}%`;
  let selectedId = $state('');
  let labelFilter = $state('');
  let message = $state('');
  let form = $state<'position' | 'event' | null>(null);
  let editingPosition = $state<Investment | null>(null);
  let editingEvent = $state<InvestmentEvent | null>(null);
  let name = $state(''); let label = $state('Other'); let note = $state('');
  let status = $state<'open' | 'closed'>('open'); let valuation = $state(''); let valuedAt = $state(localDateTime());
  let eventKind = $state<InvestmentEventKind>('cost'); let amount = $state(''); let occurredAt = $state(localDateTime());
  let linkMode = $state<'new' | 'existing'>('new'); let cashId = $state(''); let eventPositionId = $state('');
  let formError = $state('');
  let deletion = $state<{ id: string; type: 'position' | 'event'; name: string } | null>(null);
  let deleteCash = $state(false); let deleteError = $state('');
  const stats = $derived(ledger.investments.map(i => investmentStats(ledger, i.id)));
  const filtered = $derived(stats.filter(s => !labelFilter || s.position.label === labelFilter));
  const selected = $derived(stats.find(s => s.position.id === selectedId) ?? filtered[0]);
  const labels = $derived([...new Set(['Gold', 'Software', 'Subscription', 'Other', ...ledger.investments.map(i => i.label)])]);
  const closed = $derived(stats.filter(s => s.position.status === 'closed'));
  const closedCosts = $derived(closed.reduce((s, i) => s + i.costMinor, 0));
  const closedNet = $derived(closed.reduce((s, i) => s + (i.realizedMinor ?? 0), 0));
  const linkedIds = $derived(new Set(ledger.investmentEvents.map(e => e.entryId)));
  const cashCandidates = $derived(ledger.entries.filter(e => e.account === 'investment' && e.kind === (eventKind === 'return' ? 'income' : 'expense') && !linkedIds.has(e.id)));
  function modal(node: HTMLDialogElement) { node.showModal(); return { destroy: () => node.close() }; }
  function startPosition(position: Investment | null = null) {
    editingPosition = position; name = position?.name ?? ''; label = position?.label ?? 'Other'; note = position?.note ?? '';
    status = position?.status ?? 'open'; valuation = position?.valuation ? (position.valuation.amountMinor / 100).toFixed(2) : '';
    valuedAt = localDateTime(position?.valuation ? new Date(position.valuation.valuedAt) : new Date()); formError = ''; form = 'position';
  }
  function startEvent(id: string, event: InvestmentEvent | null = null) {
    eventPositionId = id; editingEvent = event; eventKind = event?.kind ?? 'cost'; amount = event ? (event.amountMinor / 100).toFixed(2) : '';
    note = event?.note ?? ''; occurredAt = localDateTime(event ? new Date(event.occurredAt) : new Date());
    linkMode = 'new'; cashId = ''; formError = ''; form = 'event';
  }
  async function save(event: SubmitEvent) {
    event.preventDefault(); formError = '';
    try {
      if (form === 'position') {
        if (!name.trim() || !label.trim()) throw new Error('Add an investment name and label.');
        const value = status === 'open' && valuation.trim() ? { amountMinor: parseNonNegativeAmount(valuation), valuedAt: occurrenceTime(valuedAt, editingPosition?.valuation?.valuedAt) } : undefined;
        const id = editingPosition?.id ?? crypto.randomUUID(); const timestamp = new Date().toISOString();
        if (await commit(current => {
          const existing = current.investments.find(i => i.id === id);
          if (editingPosition && !existing) throw new Error('This investment was deleted. Reopen the form.');
          const position: Investment = { id, name: name.trim(), label: label.trim(), note: note.trim(), status, ...(value ? { valuation: value } : {}), createdAt: existing?.createdAt ?? timestamp, updatedAt: timestamp };
          return { ...current, investments: [...current.investments.filter(i => i.id !== id), position] };
        })) { selectedId = id; message = 'Investment saved. Add its costs and cash returned below.'; form = null; }
        else formError = getError() || 'Could not save the investment.';
      } else {
        if (!note.trim()) throw new Error('Add an event note.');
        if (!editingEvent && linkMode === 'existing' && !cashId) throw new Error('Choose an existing cash transaction.');
        const linked = !editingEvent && linkMode === 'existing' ? ledger.entries.find(e => e.id === cashId) : undefined;
        const amountMinor = linked?.amountMinor ?? parseNonNegativeAmount(amount);
        if (await commit(current => recordInvestmentEvent(current, { investmentId: eventPositionId, kind: eventKind, amountMinor, note, localTime: occurredAt, ...(editingEvent ? { id: editingEvent.id } : {}), ...(linked ? { existingEntryId: linked.id } : {}) }))) { message = linked ? 'Cash entry linked once. No duplicate transaction was created.' : 'Investment event and cash entry saved together.'; selectedId = eventPositionId; form = null; }
        else formError = getError() || 'Could not save this investment event.';
      }
    } catch (e) { formError = e instanceof Error ? e.message : 'Check the amount and date.'; }
  }
  function confirmRemoval(id: string, type: 'position' | 'event', name: string) { deletion = { id, type, name }; deleteCash = false; deleteError = ''; }
  async function remove() {
    if (!deletion) return;
    const { id, type } = deletion;
    if (await commit(current => type === 'position' ? removeInvestment(current, id, deleteCash) : removeInvestmentEvent(current, id, deleteCash))) { deletion = null; message = deleteCash ? 'Tracking and its linked cash entries removed.' : 'Tracking removed. Its cash transactions remain in your ledger.'; }
    else deleteError = getError() || 'Could not remove this record.';
  }
</script>

<div class="investment-space">
  {#if message}<p class="finance-notice" role="status"><Icon name="check" size={17} />{message}</p>{/if}
  <div class="insight-cards"><article class="panel insight-card"><span class="eyebrow">RECORDED INVESTMENT COSTS</span><h2>EGP {money(stats.reduce((sum, s) => sum + s.costMinor, 0))}</h2><p>Purchase/contribution costs. Funding transfers are excluded.</p></article><article class="panel insight-card"><span class="eyebrow">TOTAL CASH RETURNED</span><h2>EGP {money(stats.reduce((sum, s) => sum + s.returnedMinor, 0))}</h2><p>Cash received, including returned principal. This is not profit.</p></article><article class="panel insight-card"><span class="eyebrow">CLOSED POSITIONS</span><h2 class:budget-warning={closedNet < 0}>EGP {money(closedNet)}</h2><p>{closed.length} closed · Weighted realized ROI {roi(closedCosts > 0 ? closedNet / closedCosts * 100 : null)}.</p></article></div>
  <section class="panel"><div class="section-heading"><div><h2>Your investments</h2><p>Optional tracking for gold, software, or anything you invest in.</p></div><button class="primary-button small" disabled={disabled || busy} onclick={() => startPosition()}><Icon name="plus" size={16} /> Add investment</button></div><div class="investment-filter"><label>Label<select bind:value={labelFilter} onchange={() => selectedId = ''}><option value="">All labels</option>{#each [...new Set(ledger.investments.map(i => i.label))] as item}<option value={item}>{item}</option>{/each}</select></label></div>{#if !filtered.length}<div class="empty-state"><span class="empty-icon"><Icon name="spark" size={28} /></span><h3>{ledger.investments.length ? 'No investments with this label' : 'Track an investment when you need to'}</h3><p>Add a position, then record costs, fees, cash returned and extra losses. You can leave this section empty.</p></div>{:else}<div class="investment-grid">{#each filtered as item (item.position.id)}<article class="investment-card" class:chosen={selected?.position.id === item.position.id}><div class="investment-title"><span class="tiny-label">{item.position.label} · {item.position.status}</span><button class="icon-button" aria-label={`Edit investment ${item.position.name}`} disabled={disabled || busy} onclick={() => startPosition(item.position)}><Icon name="edit" size={16} /></button></div><h3>{item.position.name}</h3>{#if item.position.status === 'closed'}<p class="investment-result" class:budget-warning={(item.realizedMinor ?? 0) < 0}>{roi(item.roiPercent)}</p><p class="goal-detail">Realized {item.realizedMinor === 0 ? 'break-even' : (item.realizedMinor ?? 0) > 0 ? 'profit' : 'loss'} · EGP {money(item.realizedMinor ?? 0)}</p>{:else}<p class="investment-result">{item.estimatedMinor === null ? 'Open position' : roi(item.estimatedRoiPercent)}</p><p class="goal-detail">{item.estimatedMinor === null ? 'No final profit/loss until closed. Add a valuation for an estimate.' : `Estimated total result EGP ${money(item.estimatedMinor)} — includes unrealized value.`}</p>{/if}<button class="secondary-button small" onclick={() => selectedId = item.position.id}>View events & details</button></article>{/each}</div>{/if}</section>
  {#if selected}<section class="panel"><div class="section-heading"><div><h2>{selected.position.name}</h2><p>{selected.position.note || `${selected.position.label} · ${selected.position.status}`}</p></div><button class="primary-button small" disabled={disabled || busy} onclick={() => startEvent(selected.position.id)}><Icon name="plus" size={16} /> Add cash event</button></div><dl class="investment-figures"><div><dt>Costs</dt><dd>EGP {money(selected.costMinor)}</dd></div><div><dt>Cash returned</dt><dd>EGP {money(selected.returnedMinor)}</dd></div><div><dt>Fees + extra losses</dt><dd>EGP {money(selected.feesMinor + selected.lossesMinor)}</dd></div><div><dt>Net cash flow so far</dt><dd>EGP {money(selected.netCashMinor)}</dd></div></dl>{#if selected.position.valuation}<p class="scenario-help">Manual remaining value: EGP {money(selected.position.valuation.amountMinor)}, valued {new Date(selected.position.valuation.valuedAt).toLocaleString('en-GB')}. This is not cash and does not increase any account balance.</p>{/if}<div class="finance-policy"><p>Realized profit/loss = total cash returned − costs − fees − additional losses. Realized ROI divides that result by costs. Returning EGP 20 on a cost of EGP 20 is break-even; EGP 40 returned is EGP 20 profit. Open positions show cash flow and optional manually valued estimates.</p><p>Funding the investment account is a transfer, not a cost. Every positive cash event creates or links one investment-account transaction. Edit linked amounts/time here so reporting and account balances stay consistent.</p></div>{#if !selected.events.length}<div class="empty-state"><p>No costs or returns recorded. Add the first event or link a transaction already in your investment account.</p></div>{:else}<div class="entry-list">{#each [...selected.events].sort((a, b) => b.occurredAt.localeCompare(a.occurredAt)) as event (event.id)}<article class="entry-row"><span class="entry-icon" class:income={event.kind === 'return'}><Icon name={event.kind === 'return' ? 'down' : 'up'} size={18} /></span><div class="entry-description"><h3>{eventLabels[event.kind]} · {event.note}</h3><p>{new Date(event.occurredAt).toLocaleString('en-GB')} · {event.entryId ? 'Linked to one cash entry' : 'Zero cash received · no cash entry'}</p></div><span class="entry-amount" class:positive={event.kind === 'return'}>{event.kind === 'return' ? '+' : '−'}{money(event.amountMinor)}<small>EGP</small></span><div class="entry-actions"><button class="icon-button" aria-label={`Edit investment event ${event.note}`} disabled={disabled || busy} onclick={() => startEvent(selected.position.id, event)}><Icon name="edit" size={16} /></button><button class="icon-button delete-button" aria-label={`Remove investment event ${event.note}`} disabled={disabled || busy} onclick={() => confirmRemoval(event.id, 'event', event.note)}><Icon name="trash" size={16} /></button></div></article>{/each}</div>{/if}<div class="investment-footer"><button class="text-button" disabled={disabled || busy} onclick={() => startPosition(selected.position)}>Edit status / manual valuation <Icon name="edit" size={15} /></button><button class="text-button destructive-text" disabled={disabled || busy} onclick={() => confirmRemoval(selected.position.id, 'position', selected.position.name)}>Remove investment tracking <Icon name="trash" size={15} /></button></div></section>{/if}
</div>

{#if form}<dialog use:modal aria-labelledby="investment-form-title" oncancel={(event) => { if (busy) event.preventDefault(); else form = null; }}><div class="dialog-content"><div class="dialog-heading"><div><p class="eyebrow">KEEP THE NUMBERS HONEST</p><h2 id="investment-form-title">{form === 'position' ? editingPosition ? 'Edit investment' : 'Add investment' : editingEvent ? 'Edit cash event' : 'Add investment event'}</h2></div><button class="icon-button" aria-label="Close investment form" disabled={busy} onclick={() => form = null}><Icon name="close" /></button></div><form onsubmit={save}><fieldset disabled={busy}>{#if form === 'position'}<label class="form-label">Investment name<input bind:value={name} maxlength="120" placeholder="e.g. Gold purchase" required /></label><label class="form-label">Label<input bind:value={label} list="investment-labels" maxlength="60" required /><datalist id="investment-labels">{#each labels as item}<option value={item}></option>{/each}</datalist></label><label class="form-label">Note (optional)<input bind:value={note} maxlength="300" /></label><label class="form-label">Status<select bind:value={status}><option value="open">Open — still held or ongoing</option><option value="closed">Closed — all costs/returns recorded</option></select></label>{#if status === 'open'}<label class="form-label">Remaining value (EGP, optional)<input inputmode="decimal" bind:value={valuation} placeholder="Leave blank if unknown" /></label>{#if valuation.trim()}<label class="form-label">Valued at<input type="datetime-local" bind:value={valuedAt} required /></label>{/if}<p class="form-help">An optional manual valuation, not cash received. Leave blank when you cannot value what remains.</p>{:else}<p class="form-help">Closing means no remaining holding value. Record total cash returned (including zero), fees and extra losses first. A cost is required. You can reopen later to correct records.</p>{/if}{:else}<label class="form-label">Event type<select bind:value={eventKind} onchange={() => cashId = ''}>{#each Object.entries(eventLabels) as [key, text]}<option value={key}>{text}</option>{/each}</select></label><label class="form-label">Event note<input bind:value={note} maxlength="300" required /></label>{#if !editingEvent}<label class="form-label">Cash record<select bind:value={linkMode}><option value="new">Create a new investment-account transaction</option><option value="existing">Link an existing transaction (no duplicate)</option></select></label>{/if}{#if !editingEvent && linkMode === 'existing'}<label class="form-label">Existing investment-account {eventKind === 'return' ? 'income' : 'spending'}<select bind:value={cashId} required><option value="">Choose an unlinked transaction</option>{#each cashCandidates as cash}<option value={cash.id}>{cash.note} · EGP {money(cash.amountMinor)} · {new Date(cash.occurredAt).toLocaleDateString('en-GB')}</option>{/each}</select></label><p class="form-help">Uses its exact amount and occurrence timestamp. Already-linked transactions and funding transfers are excluded.</p>{:else}<label class="form-label">{eventKind === 'return' ? 'Total cash returned (EGP, including principal)' : eventKind === 'loss' ? 'Additional money lost (EGP)' : `${eventLabels[eventKind]} (EGP)`}<input inputmode="decimal" bind:value={amount} maxlength="13" required /></label><label class="form-label">Date & time<input type="datetime-local" bind:value={occurredAt} required /></label><p class="form-help">{editingEvent?.entryId ? 'Saving changes updates the linked transaction’s amount, type and occurrence time as well.' : eventKind === 'return' ? 'Zero is allowed if nothing came back; it creates no income transaction.' : 'This is a cash outflow, separate from moving money into your investment account.'}</p>{/if}{/if}{#if formError}<p class="form-error" role="alert">{formError}</p>{/if}<button class="primary-button full-width" type="submit">{busy ? 'Saving…' : 'Save investment record'}<Icon name="check" size={17} /></button></fieldset></form></div></dialog>{/if}
{#if deletion}<dialog use:modal aria-labelledby="investment-delete-title" oncancel={(event) => { if (busy) event.preventDefault(); else deletion = null; }}><div class="dialog-content"><h2 id="investment-delete-title">Remove {deletion.type === 'position' ? 'investment tracking' : 'this event'}?</h2><p class="dialog-copy">“{deletion.name}” {deletion.type === 'position' ? 'and all its investment events' : ''} will be removed from ROI reporting. Cash transactions stay unless you explicitly select the option below. This cannot be undone. Removing the last cost reopens a closed position.</p><label class="radio-option"><input type="checkbox" bind:checked={deleteCash} disabled={busy} /><span><strong>Also delete linked cash transactions</strong><small>This changes account balances and income/spending totals. Leave unchecked to keep the financial records.</small></span></label>{#if deleteError}<p class="form-error" role="alert">{deleteError}</p>{/if}<div class="dialog-actions"><button class="secondary-button" disabled={busy} onclick={() => deletion = null}>Keep records</button><button class="danger-button" disabled={busy} onclick={remove}>{busy ? 'Removing…' : deleteCash ? 'Delete tracking & cash' : 'Remove tracking only'}</button></div></div></dialog>{/if}
